const XLSX = require('@e965/xlsx');
const rows = $input.all().map(i => i.json);
const num = v => Number(v) || 0;

// ---- DATA tab: all merged rows, in order ----
const dataHeader = ['التاريخ', 'اليوم', 'المنتج', 'الكمية', 'الإجمالي'];
const dataAoa = [dataHeader];
for (const r of rows) dataAoa.push([r['التاريخ'], r['اليوم'], r['المنتج'], num(r['الكمية']), num(r['الإجمالي'])]);

// ---- totals per day and per product ----
const byDay = {}, dayOrder = [];
const byProd = {}, prodOrder = [];
for (const r of rows) {
  const d = r['التاريخ'];
  if (!(d in byDay)) { byDay[d] = { day: r['اليوم'], qty: 0, rev: 0 }; dayOrder.push(d); }
  byDay[d].qty += num(r['الكمية']); byDay[d].rev += num(r['الإجمالي']);
  const p = r['المنتج'];
  if (!(p in byProd)) { byProd[p] = { qty: 0, rev: 0 }; prodOrder.push(p); }
  byProd[p].qty += num(r['الكمية']); byProd[p].rev += num(r['الإجمالي']);
}
let gQty = 0, gRev = 0;
for (const d of dayOrder) { gQty += byDay[d].qty; gRev += byDay[d].rev; }

// ---- SUMMARY tab ----
const sumAoa = [];
sumAoa.push(['ملخص المبيعات الأسبوعية (SAMPLE DATA)']);
sumAoa.push([]);
sumAoa.push(['الإجمالي لكل يوم']);
sumAoa.push(['اليوم', 'التاريخ', 'إجمالي الكمية', 'إجمالي المبيعات']);
for (const d of dayOrder) sumAoa.push([byDay[d].day, d, byDay[d].qty, byDay[d].rev]);
sumAoa.push([]);
sumAoa.push(['الإجمالي لكل منتج']);
sumAoa.push(['المنتج', 'إجمالي الكمية', 'إجمالي المبيعات']);
for (const p of prodOrder) sumAoa.push([p, byProd[p].qty, byProd[p].rev]);
sumAoa.push([]);
sumAoa.push(['الإجمالي العام', '', gQty, gRev]);

const wb = XLSX.utils.book_new();
XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(dataAoa), 'البيانات الأسبوعية');
XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(sumAoa), 'الملخص');
const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
const bin = await this.helpers.prepareBinaryData(Buffer.from(buf), 'weekly-summary.xlsx',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
return [{ json: { files: 7, rows: rows.length, days: dayOrder.length, products: prodOrder.length,
  grand_qty: gQty, grand_revenue: gRev }, binary: { data: bin } }];
